el ? el.outerHTML.substring(0,300) : 'not found'

// Look for the title field in the options pane - search for label text
let labels = Array.from(document.querySelectorAll('label, [class*="field"]')).map(l => l.textContent.trim()).filter(t => t.toLowerCase().includes('title')).slice(0,10);
JSON.stringify(labels)

// The options pane may need scrolling or the Panel options section may be collapsed. Check for collapsible sections
let sections = Array.from(document.querySelectorAll('button, [role="button"], summary')).map(b => b.textContent.trim()).filter(t => t && t.length < 40).slice(0,40);
JSON.stringify(sections)

// The right options pane might not be visible. Check the panel title input via the standard Grafana selector
let el = document.querySelector('input[aria-label="Panel Title"], [data-testid="title-input"] input, input[name="Panel title"]');
el ? el.outerHTML.substring(0,300) : 'checking page structure: ' + document.querySelectorAll('input').length + ' inputs total'

// The options pane is likely below the fold. Scroll the right pane into view
let pane = document.querySelector('[data-testid="options-pane"]');
if (pane) { pane.scrollTop = 0; pane.scrollIntoView(); 'pane scrolled' } else {
  // try the second column
  let cols = document.querySelectorAll('div[class*="panelEditorContentView"]');
  cols.length + ' cols found'
}

// Find the options pane by looking for the "Panel options" heading
let headings = Array.from(document.querySelectorAll('h2, h3, h4, [role="heading"]')).map(h => h.textContent.trim()).slice(0,30);
JSON.stringify(headings)

// The options pane isn't rendered. The right pane may be collapsed. Look for a toggle or the pane container
let containers = Array.from(document.querySelectorAll('div')).filter(d => d.getAttribute('aria-label') && d.getAttribute('aria-label').toLowerCase().includes('option')).map(d => d.getAttribute('aria-label')).slice(0,10);
JSON.stringify(containers)

// Check the layout: the editor has a right pane with tabs. Look for tab buttons
let tabs = Array.from(document.querySelectorAll('[role="tab"], [class*="Tab"]')).map(t => t.textContent.trim() + '|' + (t.getAttribute('aria-selected')||'')).slice(0,20);
JSON.stringify(tabs)

// The right pane may be hidden behind a toggle. Check the main editor layout structure
let main = document.querySelector('main');
let rects = Array.from(main.querySelectorAll('div')).filter(d => d.offsetHeight > 300 && d.offsetWidth > 200).slice(0,8).map(d => ({w: d.offsetWidth, h: d.offsetHeight, cls: (d.className||'').toString().substring(0,60)}));
JSON.stringify(rects)

// The options pane is likely off-screen to the right or needs scrolling. Check for the pane resize widget and the pane itself
let sep = document.querySelector('[aria-label="Pane resize widget"]');
let nextSibling = sep ? sep.nextElementSibling : null;
nextSibling ? {visible: nextSibling.offsetHeight, w: nextSibling.offsetWidth, html: nextSibling.outerHTML.substring(0,200)} : 'no separator'

// The right pane exists (317px wide, overflow hidden). The Panel options section may be collapsed. Find collapsible section buttons inside it
let pane = document.querySelector('[aria-label="Pane resize widget"]').nextElementSibling;
let btns = Array.from(pane.querySelectorAll('button')).map(b => ({text: b.textContent.trim().substring(0,40), expanded: b.getAttribute('aria-expanded')}));
JSON.stringify(btns.slice(0,20))

// Get a unique selector for the collapsed "Text" section button in the options pane
let pane = document.querySelector('[aria-label="Pane resize widget"]').nextElementSibling;
let btn = Array.from(pane.querySelectorAll('button')).find(b => b.textContent.trim() === 'Text' && b.getAttribute('aria-expanded') === 'false');
btn ? btn.getAttribute('aria-controls') + '|' + btn.id + '|' + btn.className : 'not found'

// Find the section header containing the "Text" button - get its parent structure to build a selector
let pane = document.querySelector('[aria-label="Pane resize widget"]').nextElementSibling;
let btn = Array.from(pane.querySelectorAll('button')).find(b => b.textContent.trim() === 'Text' && b.getAttribute('aria-expanded') === 'false');
let section = btn.closest('[class*="section"], [class*="collaps"]');
section ? section.className : 'parent: ' + btn.parentElement.className

// Build nth-of-type selector for the collapsed Text section button
let pane = document.querySelector('[aria-label="Pane resize widget"]').nextElementSibling;
let btns = Array.from(pane.querySelectorAll('button'));
let idx = btns.findIndex(b => b.textContent.trim() === 'Text' && b.getAttribute('aria-expanded') === 'false');
let path = [];
let el = btns[idx];
while (el && el !== pane) { let parent = el.parentElement; path.unshift(Array.from(parent.children).indexOf(el)); el = parent; }
'button index in pane: ' + idx + ' path: ' + JSON.stringify(path)

