let info = scrollers.map(s => ({sh: s.scrollHeight, ch: s.clientHeight, cls: s.className.toString().substring(0,40)}));
JSON.stringify(info.slice(0,5))

// The pane itself is 860px tall but content is cut. The pane div has overflow:hidden. Its inner content must scroll. Check the pane's children heights
