let kids = Array.from(pane.querySelectorAll('div')).filter(d => d.scrollHeight > d.clientHeight + 50 && d.clientHeight > 100);
let info = kids.map(k => ({sh: k.scrollHeight, ch: k.clientHeight, cls: k.className.toString().substring(0,50)}));
JSON.stringify(info.slice(0,8))

